SELECT SUM(ST_Area("geometry"::geography)) / 10000 AS total_area_ha
FROM public.cq_land_use_dltb
WHERE "DLMC" = '水田';

SELECT ROUND(SUM(ST_Length("shape"::geography)) / 1000.0, 2) AS total_length_km
FROM public.cq_osm_roads
WHERE "oneway" = 'T' OR "oneway" = '1';

SELECT "jqmc", ST_Area("shape"::geography) AS area_sqm
FROM public.cq_historic_districts
ORDER BY area_sqm DESC;

SELECT ROUND(SUM(ST_Area("geometry"::geography)) / 1000000, 4) AS total_area_sq_km
FROM public.cq_land_use_dltb
WHERE "DLMC" = '茶园';

SELECT COALESCE(ROUND(SUM(ST_Length("geometry"::geography)) / 1000.0, 2), 0) AS total_length_km
FROM public.cq_osm_roads_2021
WHERE "fclass" = 'motorway';

SELECT ROUND(AVG(ST_Area("geometry"::geography)), 2) AS avg_area_sqm
FROM public.cq_buildings_2021
WHERE "Floor" > 30;

SELECT ROUND(SUM(ST_Area("geometry"::geography)) / 10000, 2) AS total_area_ha
FROM public.cq_land_use_dltb
WHERE "DLMC" = '有林地';

SELECT SUM(ST_Area("geometry"::geography)) / 1000000 AS total_area_sq_km
FROM public.cq_land_use_dltb
WHERE "ZLDWMC" LIKE '%茶园%';

SELECT ST_Envelope(ST_Collect("geometry"::geometry)) AS bounding_box
FROM public.cq_osm_roads_2021
WHERE "fclass" = 'footway';

SELECT
  (SELECT "常住人口" FROM public.cq_district_population WHERE "区划名称" = '渝中区' LIMIT 1) AS yuzhong_permanent_population,
  (SELECT COUNT(*) FROM public.cq_amap_poi_2024 WHERE "类型" LIKE '%银行%') AS bank_count;

SELECT "name", "fclass"
FROM public.cq_osm_roads
LIMIT 100;
